// Oeste LivePulseDot — Huntington theme (v0.2.0).
// Copy-paste ready. Requires: React 18+, Tailwind with arbitrary values, JSX transform.
// Requires Huntington tokens: import src/tokens.css once (or copy src/tokens.json).
// Source: https://github.com/eric2busy/Oeste/blob/main/huntington/src/index.js
// Docs: https://oeste.hiddeninwest.com/huntington/#/components/live-pulse-dot

export function LivePulseDot() {
  return (
    <span aria-hidden="true" className="relative inline-flex h-6 w-6 shrink-0 items-center justify-center">
      <span className="absolute inset-0 rounded-full border-[1.5px] border-[var(--color-pulse)]" />
      <span className="absolute h-2 w-2 rounded-full bg-[var(--color-pulse)]" />
    </span>
  );
}
